package ru.stepanov.selfcontrol.scenario; import jakarta.persistence.*; import ru.stepanov.selfcontrol.banking.PaymentToken; import ru.stepanov.selfcontrol.common.Money; import java.util.*; @Embeddable public class DebitConfig{ @Embedded @AttributeOverrides({@AttributeOverride(name="amount",column=@Column(name="debit_amount",precision=19,scale=2)),@AttributeOverride(name="currency",column=@Column(name="debit_currency"))}) private Money debitAmount; @Embedded @AttributeOverride(name="value",column=@Column(name="recipient_payment_token")) private PaymentToken recipientPaymentToken; private UUID acceptanceId; private UUID sourceAccountId; public Money getDebitAmount(){return debitAmount;} public void setDebitAmount(Money debitAmount){this.debitAmount=debitAmount;} public PaymentToken getRecipientPaymentToken(){return recipientPaymentToken;} public void setRecipientPaymentToken(PaymentToken recipientPaymentToken){this.recipientPaymentToken=recipientPaymentToken;} public UUID getAcceptanceId(){return acceptanceId;} public void setAcceptanceId(UUID acceptanceId){this.acceptanceId=acceptanceId;} public UUID getSourceAccountId(){return sourceAccountId;} public void setSourceAccountId(UUID sourceAccountId){this.sourceAccountId=sourceAccountId;} }
